   161→  @Override
   162→  public AggregatorFactory getCombiningFactory()
   163→  {
   164→    return new JavaScriptAggregatorFactory(name, Collections.singletonList(name), fnCombine, fnReset, fnCombine, config);
   165→  }
   166→
   167→  @Override
   168→  public AggregatorFactory getMergingFactory(AggregatorFactory other) throws AggregatorFactoryNotMergeableException
   169→  {
   170→    if (other.getName().equals(this.getName()) && other.getClass() == this.getClass()) {
   171→      JavaScriptAggregatorFactory castedOther = (JavaScriptAggregatorFactory) other;
   172→      if (this.fnCombine.equals(castedOther.fnCombine) && this.fnReset.equals(castedOther.fnReset)) {
