   259→      return ByteBuffer.allocate(1 + fieldNameBytes.length + sha1.length)
   260→                       .put(AggregatorUtil.JS_CACHE_TYPE_ID)
   261→                       .put(fieldNameBytes)
   262→                       .put(sha1)
   263→                       .array();
   264→    }
   265→    catch (NoSuchAlgorithmException e) {
